export function createGenerationEvidenceBundle({job,result,evaluation,provenance}={}){return {version:'generation-evidence-bundle-v1',jobId:job?.jobId||null,status:result?.status||job?.status||'unknown',media:result?.mediaUrl?{url:result.mediaUrl,type:result.mediaType||null,duration:result.duration||0}:null,evaluation:evaluation||null,provenance:provenance||result?.provenance||null,complete:Boolean(result?.mediaUrl&&evaluation&&provenance)};}
